package ai.decisionos.aside;
import android.app.Activity;import org.json.*;import org.xmlpull.v1.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;
/** Public metadata fetch only; bounded RSS, one active fetch per owned goal. */
public final class MediaRepository {
 static final ExecutorService executor=Executors.newFixedThreadPool(2);static final Set<String> active=Collections.synchronizedSet(new HashSet<>());
 interface Done{void accept(String s);}
 static void fetch(Activity a,GoalStore unused,String gid,String query,String language,boolean recent,Done done){if(!active.add(gid)){done.accept("이미 조회 중이야.");return;}executor.submit(()->{String message="";try(GoalStore s=new GoalStore(a.getApplicationContext())){JSONObject goal=s.goal(gid);long now=System.currentTimeMillis();String key=query+"|"+language+"|"+recent;if(key.equals(goal.optString("newsKey"))&&now-goal.optLong("newsAt")<600000){message="10분 이내에 확인한 저장 결과야.";}else{
  String q=query+(recent?" when:7d":"");String lang="en".equals(language)?"en-US":"ko";URL u=new URL("https://news.google.com/rss/search?q="+GoalRules.enc(q)+"&hl="+lang+"&gl="+(lang.equals("ko")?"KR":"US")+"&ceid="+(lang.equals("ko")?"KR:ko":"US:en"));HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Nubi/0.2 public RSS reader");try{int status=c.getResponseCode();if(status!=200)throw new IOException(status==429?"rate_limited":"HTTP "+status);ByteArrayOutputStream data=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){if(data.size()+n>1048576)throw new IOException("Response too large");data.write(buf,0,n);}}XmlPullParser p=XmlPullParserFactory.newInstance().newPullParser();p.setFeature(XmlPullParser.FEATURE_PROCESS_NAMESPACES,false);p.setFeature(XmlPullParser.FEATURE_PROCESS_DOCDECL,false);p.setInput(new ByteArrayInputStream(data.toByteArray()),"UTF-8");JSONObject item=null;int count=0;for(int event=p.getEventType();event!=XmlPullParser.END_DOCUMENT&&count<15;event=p.next()){if(event==XmlPullParser.START_TAG){String tag=p.getName();if(tag.equals("item"))item=new JSONObject();else if(item!=null&&Arrays.asList("title","link","pubDate","source").contains(tag)){String text=p.nextText();GoalStore.put(item,tag,text);}}else if(event==XmlPullParser.END_TAG&&p.getName().equals("item")&&item!=null){String url=item.optString("link");if(!GoalRules.safe(url))continue;JSONObject row=new JSONObject();String id=UUID.nameUUIDFromBytes((gid+"|GoogleNews|"+url).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();for(JSONObject old:s.list("contents",gid))if(id.equals(old.optString("id")))row=old;GoalStore.put(row,"id",id);GoalStore.put(row,"title",item.optString("title"));GoalStore.put(row,"url",url);GoalStore.put(row,"provider","Google News");GoalStore.put(row,"kind","뉴스");GoalStore.put(row,"author",item.optString("source","미확인"));GoalStore.put(row,"published",item.optString("pubDate","미확인"));GoalStore.put(row,"checkedAt",now);GoalStore.put(row,"query",query);s.save("contents",gid,row);count++;item=null;}}JSONObject delta=new JSONObject();GoalStore.put(delta,"newsStatus",count>0?"live · "+count+"건":"live · 결과 없음");GoalStore.put(delta,"newsChecked",java.time.Instant.now().toString());GoalStore.put(delta,"newsAt",now);GoalStore.put(delta,"newsKey",key);s.patchGoal(gid,delta);message="뉴스 "+count+"건을 가져왔어.";}finally{c.disconnect();}}
 }catch(Exception e){message="뉴스 조회 실패 · 다른 공급자를 이용할 수 있어.";try(GoalStore s=new GoalStore(a.getApplicationContext())){JSONObject delta=new JSONObject();GoalStore.put(delta,"newsStatus",e.getMessage()!=null&&e.getMessage().contains("rate_limited")?"rate_limited":"failed");s.patchGoal(gid,delta);}catch(Exception ignored){}}finally{active.remove(gid);}final String result=message;a.runOnUiThread(()->done.accept(result));});}
 private MediaRepository(){}
}
